import { describe, it, expect } from 'vitest'
import { addressSources, type RegionKey } from '../addressSources.js'

// ============================================================================
// Type safety — compile-time check that keys are literal union types
// ============================================================================

describe('Type safety', () => {
  it('RegionKey is a union of the three Belgian region codes', () => {
    // This test verifies at runtime that the type system works correctly.
    // If someone tries to assign an invalid key, TypeScript will catch it.
    const validKeys: RegionKey[] = ['BE-VLG', 'BE-BRU', 'BE-WAL']

    for (const key of validKeys) {
      expect(addressSources).toHaveProperty(key)
    }
  })

  it('all values are non-empty strings matching BOSA URL pattern', () => {
    const bosaUrlPattern = /^https:\/\/opendata\.bosa\.be\/download\/best\/openaddress-be[a-z]{3}\.zip$/i

    for (const [key, url] of Object.entries(addressSources)) {
      expect(url).toMatch(bosaUrlPattern)
      expect(key.startsWith('BE-')).toBe(true)
    }
  })
})

// ============================================================================
// Content — all three regions present with correct URLs
// ============================================================================

describe('Region coverage', () => {
  it('contains BE-VLG (Flanders)', () => {
    expect(addressSources['BE-VLG']).toBe(
      'https://opendata.bosa.be/download/best/openaddress-bevlg.zip'
    )
  })

  it('contains BE-BRU (Brussels)', () => {
    expect(addressSources['BE-BRU']).toBe(
      'https://opendata.bosa.be/download/best/openaddress-bebru.zip'
    )
  })

  it('contains BE-WAL (Wallonia)', () => {
    expect(addressSources['BE-WAL']).toBe(
      'https://opendata.bosa.be/download/best/openaddress-bewal.zip'
    )
  })

  it('has exactly three region entries', () => {
    const keys = Object.keys(addressSources) as RegionKey[]
    expect(keys).toHaveLength(3)
    expect(keys).toContain('BE-VLG')
    expect(keys).toContain('BE-BRU')
    expect(keys).toContain('BE-WAL')
  })

  it('all URLs are unique', () => {
    const urls = Object.values(addressSources)
    expect(new Set(urls).size).toBe(urls.length)
  })
})

/**
 * Address Sources — BOSA OpenData download URLs by region.
 *
 * Maps Belgian region keys to their corresponding BOSA BEVLG dataset
 * download URLs. Adding a new region requires only appending an entry here.
 *
 * @example
 * ```ts
 * import { addressSources, type RegionKey } from '@/config/addressSources.js'
 * const url = addressSources['BE-VLG']
 * ```
 */

// ── Region key union — the single source of truth for valid keys ──────────────

/** Valid Belgian region codes used in address sync operations. */
export type RegionKey = 'BE-VLG' | 'BE-BRU' | 'BE-WAL'

// ── URL mapping — keyed by RegionKey, typed to enforce key safety ────────────

/**
 * Maps each Belgian region code to its BOSA OpenData download URL.
 * The type `Record<RegionKey, string>` ensures every defined key is present
 * and that only valid keys can be used as indices.
 */
export const addressSources: Record<RegionKey, string> = {
  /** Flanders — active dataset (~617 MB CSV → ~85K unique streets) */
  'BE-VLG': 'https://opendata.bosa.be/download/best/openaddress-bevlg.zip',

  /** Brussels — placeholder URL (not yet synced) */
  'BE-BRU': 'https://opendata.bosa.be/download/best/openaddress-bebru.zip',

  /** Wallonia — placeholder URL (not yet synced) */
  'BE-WAL': 'https://opendata.bosa.be/download/best/openaddress-bewal.zip',
}

import { describe, it, expect } from 'vitest'
import { addressSources } from '../addressSources.js'

/**
 * Live network probes for BOSA OpenData endpoints.
 *
 * These tests make real HTTPS requests to opendata.bosa.be and are
 * **environment-sensitive**: they require outbound network access AND a
 * working TLS trust chain. They are skipped by default so that `pnpm test`
 * stays hermetic and fast.
 *
 * Run them explicitly with:
 *
 *   RUN_NETWORK_TESTS=1 pnpm --filter @pi-skeleton/server test
 *
 * In a corporate environment behind a TLS-inspecting proxy, also export:
 *
 *   NODE_EXTRA_CA_CERTS=/path/to/corporate-root-ca.crt
 *
 * @see https://nodejs.org/api/cli.html#node_extra_ca_certsfile
 */

const runNetworkTests = process.env.RUN_NETWORK_TESTS === '1'

// Vitest's `it` is bound at import time; capture the gated version once.
// Using `it.skip` keeps the test report showing "skipped" rather than hiding
// the cases entirely, which is what we want for CI visibility.
const networkIt = runNetworkTests ? it : it.skip

const describeIfNetwork = runNetworkTests ? describe : describe.skip

// ============================================================================
// URL resolution — verify endpoints respond (no 403/404)
// ============================================================================

describeIfNetwork('URL resolution (live network)', () => {
  networkIt('BE-VLG URL resolves without 4xx error', async () => {
    const response = await fetch(addressSources['BE-VLG'], { method: 'HEAD' })
    expect(response.status).not.toBeGreaterThanOrEqual(400)
  }, 15000)

  networkIt('BE-BRU URL resolves without 4xx error', async () => {
    const response = await fetch(addressSources['BE-BRU'], { method: 'HEAD' })
    expect(response.status).not.toBeGreaterThanOrEqual(400)
  }, 15000)

  networkIt('BE-WAL URL resolves without 4xx error', async () => {
    const response = await fetch(addressSources['BE-WAL'], { method: 'HEAD' })
    expect(response.status).not.toBeGreaterThanOrEqual(400)
  }, 15000)

  networkIt('all URLs return Content-Disposition header (indicating file download)', async () => {
    for (const [_key, url] of Object.entries(addressSources)) {
      const response = await fetch(url, { method: 'HEAD' })
      expect(response.status).not.toBeGreaterThanOrEqual(400)
      // BOSA returns Content-Disposition for downloadable files
      const contentDisposition = response.headers.get('content-disposition')
      if (contentDisposition) {
        expect(contentDisposition.toLowerCase()).toContain('attachment')
      }
    }
  }, 20000)
})
